package com.chronos.integration.model; import com.chronos.model.pojo.BaseEntity; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter;
import com.fasterxml.jackson.annotation.JsonIgnore;
@Entity @Table(name="int_connector") @Getter @Setter public class Connector extends BaseEntity { @Column(nullable=false,length=120) private String name; @Column(nullable=false,length=30) private String type="HTTP"; @Column(name="provider_code",length=64) private String providerCode="HTTP_JSON"; @Column(name="base_url",nullable=false,length=1000) private String baseUrl; @Column(length=20) private String status="ACTIVE"; @Column(length=16) private String direction="INBOUND"; @Column(name="allowed_host",length=255) private String allowedHost; @Column(name="health_status",length=24) private String healthStatus="UNKNOWN"; @Column(name="last_checked_at") private java.time.LocalDateTime lastCheckedAt; @Column(name="timeout_ms") private Integer timeoutMs=10000; @Column(name="max_retries") private Integer maxRetries=3; @JsonIgnore @Column(name="config_json",columnDefinition="text") private String configJson="{}"; }
